    let canSendCross = server.handleMessage(
        tenantId: "acme-corp",
        token: "valid-token-123",
        targetTenantId: "victim-corp",
        message: "exfiltrated data request"
    )
    print("Cross-tenant message allowed: \(canSendCross)") // false - isolation enforced
